import {VikingOrdinaryAward} from './VikingRules';
import {vikingClusters} from './VikingWildRules';
import {VikingFall,VikingSpawn,vikingCollapse} from './VikingBoard';
export type {VikingFall,VikingSpawn} from './VikingBoard';
import {VikingChargeAction,vikingChargeAction} from './VikingFeatures';
import {VikingProgress,VikingProgressChange,vikingRecordSymbolWins} from './VikingProgress';

export interface VikingCascadeStep {
 before:number[];
 wins:VikingOrdinaryAward[];
 removed:number[];
 falls:VikingFall[];
 spawned:VikingSpawn[];
 after:number[];
 progress?:VikingProgressChange;
 chargeBefore:number;
 chargeAfter:number;
 subtotal:number;
}
export interface VikingCascadeResult {
 board:number[];
 steps:VikingCascadeStep[];
 charge:number;
 subtotal:number;
 next:VikingChargeAction;
 progress?:VikingProgress;
}
/** Cascade segment (ordinary and unambiguous god WILD substitutions).
 * A charge-effect/Ragnarok boundary is returned
 * to the dedicated feature state machine; it is NOT a settled round. The UI
 * can play before -> wins -> removal -> falls/spawn -> after without jumping
 * straight to a future final board. No math-policy RNG is guessed here. */
export function vikingOrdinaryCascade(
 initial:readonly number[],bet:number,
 refill:(column:number,row:number,step:number)=>number,
 state:{charge?:number;effectPlayed?:boolean;ragnarokPlayed?:boolean;subtotal?:number;maxSteps?:number;progress?:VikingProgress}={},
):VikingCascadeResult {
 let board=[...initial],charge=state.charge??0,subtotal=state.subtotal??0;
 let progress=state.progress?vikingRecordSymbolWins(state.progress,[]).after:undefined;
 const maxSteps=state.maxSteps??256;
 if(!Number.isSafeInteger(maxSteps)||maxSteps<1||!Number.isFinite(subtotal)||subtotal<0)throw Error('Invalid Viking cascade state');
 vikingChargeAction({hasWins:false,charge,effectPlayed:!!state.effectPlayed,ragnarokPlayed:!!state.ragnarokPlayed});
 const steps:VikingCascadeStep[]=[];
 while(true){
  const wins=vikingClusters(board,bet);
  if(!wins.length)return {board,steps,charge,subtotal,progress:progress?vikingRecordSymbolWins(progress,[]).after:undefined,next:vikingChargeAction({hasWins:false,charge,effectPlayed:!!state.effectPlayed,ragnarokPlayed:!!state.ragnarokPlayed})};
  // Never return a half-resolved cascade as a completed payable spin.
  if(steps.length>=maxSteps)throw Error('Viking cascade exceeded resolution limit');
  const before=[...board],removed=[...Array.from(new Set(wins.flatMap(w=>w.cells)))].sort((a,b)=>a-b);
  const {after,falls,spawned}=vikingCollapse(before,removed,(column,row)=>refill(column,row,steps.length));
  const change=progress?vikingRecordSymbolWins(progress,wins):undefined;
  if(change)progress=change.after;
  const chargeBefore=charge;
  charge+=removed.length;
  subtotal+=wins.reduce((sum,w)=>sum+w.amount,0);
  steps.push({before,wins,removed,falls,spawned,after:[...after],progress:change,chargeBefore,chargeAfter:charge,subtotal});
  board=after;
 }
}
