export interface PlayStats {spins:number;hits:number;moneyIn:number;moneyOut:number;recentHits:number[];}
const emptyPlayStats=():PlayStats=>({spins:0,hits:0,moneyIn:0,moneyOut:0,recentHits:[]});
function validPlayStats(value:any):value is PlayStats{return value&&['spins','hits','moneyIn','moneyOut'].every(key=>Number.isSafeInteger(value[key])&&value[key]>=0)&&value.hits<=value.spins&&Array.isArray(value.recentHits)&&value.recentHits.length<=50&&value.recentHits.every((hit:unknown)=>hit===0||hit===1);}
