import {BET_LEVELS} from './BetLevels';
import {SlotMain,SlotConfig,SpinResult,Win} from './SlotMain';
import {SlotProgress,normalizeSlotProgress,socialPresentation,packRounds} from './Social2230Rules';
export interface ContractPlayback {stage:'draw'|'collect'|'continue'|'loss';before:number[];after:number[];secured:Win[];risk:number;}
export class AngelDevilSlot extends SlotMain {
 readonly usesLocalPayouts=true;readonly columns=1;readonly rows=1;readonly paylines=[[0]];readonly bets=[...BET_LEVELS];readonly maxWin=1000;
 private progress:SlotProgress={};setProgress(p:SlotProgress){this.progress=normalizeSlotProgress(p);}
 readonly presentation=socialPresentation('세 계약 진행 · 수령 또는 계속','계약 도장');
 readonly config:SlotConfig={id:'angel-devil-contract',title:'천사와 악마의 계약',subtitle:'ANGEL AND DEVIL CONTRACT',tag:'COLLECT OR CONTINUE',color:'#332d46',accent:'#e9b0cc',description:'1릴 · 세 계약 도장 진행\n도장: 해당 계약 한 칸. 천사: 세 계약 모두 한 칸.\n매 당첨 뒤 수령/계속 선택. 계속하면 미수령 보상만 위험에 노출.\n악마는 미수령 보상·진행을 초기화. 이미 지급한 코인은 회수하지 않음.\n각 계약 4칸은 베팅 ×20 즉시 확정. AUTO는 수령.\n진행은 베팅별 저장. 보너스 구매 없음.',symbols:['붉은 계약 도장','푸른 계약 도장','보라 계약 도장','천사의 깃털','악마의 봉인'].map((name,n)=>({id:'angel-devil-contract-'+n,name,color:'#e9b0cc',weight:[20,20,20,2,38][n],payout:0}))};
 resolve(symbol:string,bet:number):SpinResult{
  if(!this.bets.includes(bet)||!this.config.symbols.some(s=>s.id===symbol))throw Error('Invalid contract draw');
  const raw=this.progress[this.config.id+':'+bet],before=raw?.length===4&&raw.slice(0,3).every(n=>n<=4)?[...raw]:[0,0,0,0],after=[...before],index=this.config.symbols.findIndex(s=>s.id===symbol),secured:Win[]=[];
  const base:SpinResult={board:[symbol],bet,payout:0,wins:secured,presentation:this.presentation};
  if(index===4){after.fill(0);base.contractFeature={stage:'loss',before,after,secured,risk:before[3]};base.progressUpdate={key:this.config.id+':'+bet,values:after};return base;}
  for(const path of index===3?[0,1,2]:[index]){if(before[path]>=4)continue;after[path]=Math.min(4,after[path]+1);if(after[path]===4)secured.push({line:0,symbol,cells:[0],amount:20*bet,multiplier:20});else after[3]+=Math.round(bet*[0,1.485,2.4,4][after[path]]);}
  base.payout=secured.reduce((s,w)=>s+w.amount,0);base.contractFeature={stage:'draw',before,after:[...after],secured,risk:after[3]};
  const branches=[true,false].map(collect=>{const values=collect?[0,0,0,0]:[...after],wins:Win[]=collect&&after[3]>0?[{line:0,symbol,cells:[0],amount:after[3],multiplier:after[3]/bet}]:[],round:SpinResult={board:[symbol],bet,payout:wins.reduce((s,w)=>s+w.amount,0),wins,contractFeature:{stage:collect?'collect':'continue',before:[...after],after:values,secured:[],risk:after[3]}};return packRounds([base,round],{featureOnly:true,progressUpdate:{key:this.config.id+':'+bet,values},presentation:this.presentation});});
  if(after[3]>=bet*100||after.slice(0,3).every(n=>n===4))return branches[0];
  return{...branches[0],featureChoices:{title:'미수령 '+after[3]+'코인 · 계속하면 악마에게 잃을 수 있습니다',labels:['수령하고 종료','보관하고 다음 회전'],results:branches,defaultIndex:0,noBonusEntry:true}};
 }
 spin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');return this.resolve(this.pick(rng),bet);}
 evaluate(board:string[],bet:number){if(board.length!==1)throw Error('Invalid board');return this.resolve(board[0],bet);}
 demoSpin(bet:number){return this.resolve(this.config.id+'-3',bet);}
}
