import type {Win} from './SlotMain';
export const HOGS_ART=['jackpot_safe','red_seven','triple_bar','double_bar','single_bar','bells','cherries','plum','lemon','watermelon','headphones','pink_pig','green_pig','red_pig','golden_pig'];
export const HOGS_EXTRA_ART=['double_pig','music_note','speaker','microphone','stage_platform'];
export const hogsSymbol=(name:string)=>'double-down-street-'+name;
export interface HogsPig {cell:number;kind:'pink'|'green'|'red'|'golden';value:number}
export interface HogsState {rows:number;remaining:number;played:number;pigs:HogsPig[]}
export type HogsEvent=
 |{kind:'green';cell:number;before:number;after:number}
 |{kind:'red';source:number;targets:{cell:number;before:number;after:number}[]}
 |{kind:'grow';source:number;beforeRows:number;afterRows:number};
export interface HogsStage {before:HogsState;afterConsume:HogsState;landed:HogsPig[];events:HogsEvent[];after:HogsState}
export interface HogsPlayback {initial:HogsState;stages:HogsStage[];final:HogsState;award:Win;triggerBoard:string[]}
export const hogsCopy=(state:HogsState):HogsState=>({...state,pigs:state.pigs.map(pig=>({...pig}))});
export function hogsStart(pigs:HogsPig[],rows=3,resetCount=3):HogsState{
 if(pigs.length<6||!Number.isInteger(rows)||rows<3||rows>8||!Number.isInteger(resetCount)||resetCount<1)throw Error('Invalid Hogs trigger');
 const result={rows,remaining:resetCount,played:0,pigs:pigs.map(pig=>({...pig}))};validatePigs(result);return result;
}
function validatePigs(state:HogsState){
 if(new Set(state.pigs.map(pig=>pig.cell)).size!==state.pigs.length||state.pigs.some(pig=>!Number.isInteger(pig.cell)||pig.cell<0||pig.cell>=state.rows*5||!['pink','green','red','golden'].includes(pig.kind)||!Number.isSafeInteger(pig.value)||pig.value<1))throw Error('Invalid Hogs pigs');
}
/** Explicit deterministic outcomes: three-reset default, +green amounts, red
 * target choices and growth counts are draft inputs, never random UI choices. */
export function hogsResolve(state:HogsState,landed:HogsPig[],greenGrowth:Record<number,number>,redTargets:Record<number,number[]>,goldRows:Record<number,number>,resetCount=3):HogsStage{
 validatePigs(state);if(state.remaining<1||!Number.isInteger(state.remaining))throw Error('Hogs respins ended');
 if(!Number.isInteger(resetCount)||resetCount<1)throw Error('Invalid Hogs reset count');
 const before=hogsCopy(state),afterConsume=hogsCopy(state);afterConsume.remaining--;afterConsume.played++;
 const after=hogsCopy(afterConsume);after.pigs.push(...landed.map(pig=>({...pig})));validatePigs(after);
 const events:HogsEvent[]=[];
 for(const pig of after.pigs.filter(pig=>pig.kind==='green')){
  const growth=greenGrowth[pig.cell]??0;if(!Number.isSafeInteger(growth)||growth<0)throw Error('Invalid green growth');
  if(growth){const previous=pig.value;pig.value+=growth;if(!Number.isSafeInteger(pig.value))throw Error('Hogs value overflow');events.push({kind:'green',cell:pig.cell,before:previous,after:pig.value});}
 }
 for(const pig of landed.filter(pig=>pig.kind==='red')){
  const cells=redTargets[pig.cell]||[];if(cells.length<1||cells.length>3||new Set(cells).size!==cells.length||cells.includes(pig.cell))throw Error('Invalid red targets');
  const targets=cells.map(cell=>{const target=after.pigs.find(item=>item.cell===cell);if(!target)throw Error('Missing red target');const previous=target.value;target.value*=2;if(!Number.isSafeInteger(target.value))throw Error('Hogs value overflow');return{cell,before:previous,after:target.value};});
  events.push({kind:'red',source:pig.cell,targets});
 }
 for(const pig of landed.filter(pig=>pig.kind==='golden')){
  const count=goldRows[pig.cell]??0;if(!Number.isInteger(count)||count<1||count>5)throw Error('Invalid golden growth');
  const previous=after.rows;after.rows=Math.min(8,after.rows+count);events.push({kind:'grow',source:pig.cell,beforeRows:previous,afterRows:after.rows});
 }
 if(landed.length)after.remaining=resetCount;
 return{before,afterConsume,landed:landed.map(pig=>({...pig})),events,after};
}
