import type {Win} from './SlotMain';

export const CHAOS_ART=['eight_ball','skull','smiley','cross','lightning','moth','brain','apple_core','tentacle','cat_wild','scatter_poster','bonus_skull','epic_skull','bonus_cat','epic_cat','inactive_mark'];
export const chaosSymbol=(name:string)=>'chaos-crew-x-'+name;
export interface ChaosState {remaining:number;played:number;bank:number[]}
export interface ChaosLanding {cell:number;kind:'add'|'multiply';value:number;epic:boolean}
export interface ChaosEvent {landing:ChaosLanding;targets:number[];before:number[];after:number[]}
export interface ChaosPlayback {
 before:ChaosState;afterConsume:ChaosState;after:ChaosState;events:ChaosEvent[];added:number;
 collection?:{values:number[];rawMultiplier:number;paidMultiplier:number;award:Win;capReached:boolean};
}
export const chaosCopy=(state:ChaosState):ChaosState=>({...state,bank:[...state.bank]});
export const chaosStart=():ChaosState=>({remaining:3,played:0,bank:[1,1,1,1,1]});
export function chaosLandingArt(landing:ChaosLanding){return chaosSymbol((landing.epic?'epic_':'bonus_')+(landing.kind==='add'?'skull':'cat'));}
/** Source-backed three-miss accumulator. Landing order is supplied explicitly;
 * same-spin ordering/distributions remain separate from this deterministic reducer. */
export function chaosResolve(state:ChaosState,landings:ChaosLanding[],bet:number,budget=bet*10000):ChaosPlayback{
 if(!Number.isInteger(state.remaining)||state.remaining<1||state.remaining>3||state.bank.length!==5||state.bank.some(value=>!Number.isSafeInteger(value)||value<1)||!Number.isSafeInteger(bet)||bet<1)throw Error('Invalid active Chaos state');
 if(!Number.isSafeInteger(budget)||budget<0||budget>bet*10000)throw Error('Invalid Chaos win budget');
 const before=chaosCopy(state),afterConsume=chaosCopy(state);afterConsume.remaining--;afterConsume.played++;
 const after=chaosCopy(afterConsume),events:ChaosEvent[]=[],cells=new Set<number>();
 for(const landing of landings){
  if(!Number.isInteger(landing.cell)||landing.cell<0||landing.cell>=25||cells.has(landing.cell)||!['add','multiply'].includes(landing.kind)||!Number.isSafeInteger(landing.value)||landing.value<(landing.kind==='add'?1:2))throw Error('Invalid Chaos landing');
  cells.add(landing.cell);const targets=landing.epic?[0,1,2,3,4]:[landing.cell%5],previous=[...after.bank];
  for(const reel of targets){after.bank[reel]=landing.kind==='add'?after.bank[reel]+landing.value:after.bank[reel]*landing.value;if(!Number.isSafeInteger(after.bank[reel]))throw Error('Chaos accumulator overflow');}
  events.push({landing:{...landing},targets,before:previous,after:[...after.bank]});
  if(after.bank.reduce((sum,value)=>sum+value,0)*bet>=budget)break;
 }
 const capReached=after.bank.reduce((sum,value)=>sum+value,0)*bet>=budget;
 const added=landings.length&&!capReached?3-after.remaining:0;if(capReached)after.remaining=0;else if(landings.length)after.remaining=3;
 const result:ChaosPlayback={before,afterConsume,after,events,added};
 if(after.remaining===0){
  const rawMultiplier=after.bank.reduce((sum,value)=>sum+value,0);if(!Number.isSafeInteger(rawMultiplier))throw Error('Chaos total overflow');
  const amount=Math.min(budget,rawMultiplier*bet),paidMultiplier=amount/bet;if(!Number.isSafeInteger(amount))throw Error('Chaos award overflow');
  result.collection={values:[...after.bank],rawMultiplier,paidMultiplier,capReached,award:{line:-1,symbol:chaosSymbol('bonus_skull'),amount,cells:[]}};
 }
 return result;
}
