import {GladiatorPreviewSlot,GLADIATOR_ART} from './GladiatorPreviewSlot';
import {GladiatorMode,GladiatorDuel,GladiatorCoin,gladiatorStart,gladiatorSymbol as s} from './GladiatorFeature';
import {gladiatorBonusStart,gladiatorBonusResolve,GLADIATOR_ARENA_VALUES,GLADIATOR_BEAST_VALUES,GLADIATOR_CENTRE_VALUES,GLADIATOR_COIN_VALUES} from './GladiatorBonus';
import {GLADIATOR_PAYS,GLADIATOR_LINES,GLADIATOR_BASE_VALUES,gladiatorBaseRound} from './GladiatorRules';
import type {SlotConfig,SpinResult,SlotPresentation} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
const WEIGHTS=[17,16,15,14,13,8,8,5,5,3,1];
/** Source-backed rules, explicitly local unpublished symbol/value probabilities. */
export class GladiatorSlot extends GladiatorPreviewSlot {
 readonly hasBonus=true;readonly usesReferencePayouts=true;readonly maxWin=10000;readonly paylines=GLADIATOR_LINES;
 readonly bets=[...BET_LEVELS];readonly bonusCalibrationKey='gladiator-lore:duel-bank-v1';readonly bonusChoiceCount=2;
 get unlockPriceTenths(){return 1000;}
 readonly presentation:SlotPresentation={evidence:'official-rules',anticipationText:'경기장 문이 열립니다',triggerText:'검투사의 결투',bonusInText:'3회 · 릴 배수 수집',hitText:'결투 승자 · 릴 확장',totalWinText:'검투사 · 총 당첨',signature:'경기장 배수 교체 · 야수 배수 누적',uiEffect:'코인 먼저 · 결투 공개 · 마지막 릴 합산',soundCue:'featureLand',anticipationHold:.35,hitHold:.25,outHold:.6};
 readonly config:SlotConfig={id:'gladiator-lore',title:'글래디에이터 로어',subtitle:'GLADIATOR LORE',tag:'결투 · 두 보너스',color:'#423842',accent:'#e4b671',description:'5×4 · 10라인\n기본 VS는 당첨 가능 릴을 확장\n경기장: 코인 적용 후 승자 배수 교체\n야수: 외곽 배수 누적 · 중앙 배수 해제\nVS 착지 시 남은 3회 복구\n보너스 종료 시 릴 배수 합산 · 최대 10,000배',symbols:GLADIATOR_ART.map((art,i)=>({id:s(art),name:art,color:'#e4b671',weight:WEIGHTS[i]||0,payout:GLADIATOR_PAYS[i]?.[2]||0}))};
 private regular(rng:()=>number){let roll=rng()*WEIGHTS.reduce((a,b)=>a+b,0);for(let i=0;i<WEIGHTS.length;i++){roll-=WEIGHTS[i];if(roll<0)return s(GLADIATOR_ART[i]);}return s('rank_10');}
 private value(values:number[],rng:()=>number){return values[Math.min(values.length-1,Math.floor(rng()*rng()*values.length))];}
 private base(bet:number,rng:()=>number):SpinResult{
  const board=Array.from({length:20},()=>this.regular(rng)),duels:GladiatorDuel[]=[];
  for(let reel=0;reel<5;reel++){
   const roll=rng(),cell=Math.floor(rng()*4)*5+reel;
   if(roll<.055){board[cell]=s('duel_swords');duels.push({reel,left:this.value(GLADIATOR_BASE_VALUES,rng),right:this.value(GLADIATOR_BASE_VALUES,rng),winner:rng()<.5?'left':'right'});}
   else if(roll<.12)board[cell]=s('arena_gate');else if(roll<.155)board[cell]=s('beast_gate');
  }
  return gladiatorBaseRound(board,bet,duels);
 }
 private bonus(base:SpinResult,mode:GladiatorMode,rng:()=>number):SpinResult{
  let state=gladiatorBonusStart(mode);const rounds=[base],budget=base.bet*this.maxWin-base.payout;
  while(state.lives>0){
   if(state.played>=1000)throw Error('Gladiator bonus did not converge');
   const board=Array.from({length:20},(_,cell)=>s(GLADIATOR_ART[cell%10])),duels:GladiatorDuel[]=[],coins:GladiatorCoin[]=[];
   for(let reel=0;reel<5;reel++){
    if(mode==='beast'&&reel===2&&!state.unlocked[2])continue;
    const roll=rng(),cell=Math.floor(rng()*4)*5+reel;
    if(roll<.13){
     const pool=mode==='arena'?GLADIATOR_ARENA_VALUES:reel===2?GLADIATOR_CENTRE_VALUES:GLADIATOR_BEAST_VALUES;
     duels.push({reel,left:mode==='arena'?state.reels[reel]:this.value(pool,rng),right:this.value(pool,rng),winner:mode==='arena'&&state.reels[reel]===0?'right':rng()<.5?'left':'right'});board[cell]=s('duel_swords');
    }else if(mode==='arena'&&roll<.20){const epic=rng()<.10;coins.push({cell,factor:this.value(GLADIATOR_COIN_VALUES,rng),epic});board[cell]=s(epic?'epic_token':'normal_token');}
   }
   const feature=gladiatorBonusResolve(state,duels,coins,base.bet,budget);state=feature.after;
   rounds.push({bet:base.bet,board,wins:feature.wins,payout:feature.wins.reduce((sum,win)=>sum+win.amount,0),gladiatorFeature:feature,freeSpinsAdded:feature.added||undefined,freeSpinsRemaining:state.lives,roundLabel:`${mode==='arena'?'경기장':'야수'} · ${state.played}회 · 남은 ${state.lives}회`,presentation:this.presentation});
  }
  return{bet:base.bet,board:[...rounds[rounds.length-1].board],wins:rounds.flatMap(round=>round.wins),payout:rounds.reduce((sum,round)=>sum+round.payout,0),rounds,freeSpinsAwarded:3,featureName:mode==='arena'?'경기장의 결투':'야수의 봉인',bonusEndReason:rounds[rounds.length-1].gladiatorFeature?.collection?.capReached?'max-win':'spins-exhausted',presentation:this.presentation};
 }
 spin(bet:number,rng:()=>number=Math.random):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid Gladiator bet');const base=this.base(bet,rng),opening=base.openingBoard||base.board;
  if(base.payout>=bet*this.maxWin)return base;
  const mode:GladiatorMode|undefined=opening.filter(id=>id===s('arena_gate')).length>=3?'arena':opening.filter(id=>id===s('beast_gate')).length>=3?'beast':undefined;
  const result=mode?this.bonus(base,mode,rng):base;result.presentation=this.presentation;return result;
 }
 evaluate(board:string[],bet:number){if(!this.bets.includes(bet))throw Error('Invalid Gladiator bet');return gladiatorBaseRound(board,bet,[]);}
 /** Purchase branches use the same natural base generator, conditioned on the
  * actual gate type. No fixed winning board or forced gate placement is used. */
 prepareBonusPurchase(bet:number,rng:()=>number):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid Gladiator bet');
  const results=(['arena','beast'] as const).map(mode=>{
   const gate=s(mode==='arena'?'arena_gate':'beast_gate');
   for(let attempt=0;attempt<100000;attempt++){
    const base=this.base(bet,rng),opening=base.openingBoard||base.board;
    if(opening.filter(id=>id===gate).length<3||base.payout>=bet*this.maxWin)continue;
    const natural=this.bonus(base,mode,rng),rounds=natural.rounds!.slice(1);
    return{bet,board:[...rounds[rounds.length-1].board],rounds,wins:rounds.flatMap(round=>round.wins),payout:rounds.reduce((sum,round)=>sum+round.payout,0),freeSpinsAwarded:3,featureName:natural.featureName,bonusEndReason:natural.bonusEndReason,presentation:this.presentation,bonusTriggerRound:{bet,board:[...opening],wins:[],payout:0,roundLabel:'BONUS TRIGGER'}};
   }
   throw Error('Gladiator '+mode+' natural entry could not be prepared');
  });
  return{...results[0],featureChoices:{title:'검투사 보너스 선택',labels:['경기장의 결투','야수의 봉인'],defaultIndex:0,results}};
 }
 demoSpin(bet:number){let seed=26213;return this.spin(bet,()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;});}
 bonusDemoSpin(bet:number,mode:GladiatorMode='arena',initialSeed=mode==='arena'?5:49){
  if(!this.bets.includes(bet))throw Error('Invalid Gladiator bet');let seed=initialSeed;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
  const board=Array.from({length:20},()=>this.regular(rng));[0,7,14].forEach(cell=>board[cell]=s(mode==='arena'?'arena_gate':'beast_gate'));
  return this.bonus(gladiatorBaseRound(board,bet,[]),mode,rng);
 }
}
