import {GoldenAtlasSlot} from './GoldenAtlasSlot';
export function goldenAtlasAudit(params:URLSearchParams){const slot=new GoldenAtlasSlot(),outcome=params.get('audit-outcome');if(['clear','region','no-win','single-win','multi-win'].includes(outcome||''))slot.demoSpin=bet=>{let seed=369281;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};slot.setProgress({});for(let i=0;i<100000;i++){const r=slot.spin(bet,rng);if(outcome==='clear'?!!r.rounds:outcome==='region'?!r.rounds&&r.atlasFeature!.moves.some(m=>m.completed):!r.rounds&&(outcome==='no-win'?r.wins.length===0:outcome==='single-win'?r.wins.length>0&&new Set(r.wins.map(w=>w.symbol)).size===1:new Set(r.wins.map(w=>w.symbol)).size>1))return r;slot.setProgress({[r.progressUpdate!.key]:r.progressUpdate!.values});}throw Error('Atlas natural sequence unavailable');};return slot;}
