import {Social2230LineSlot,socialPresentation,sumResult,SOCIAL_2230_PAYS,awardLines} from './Social2230Rules';
import {Win} from './SlotMain';
import {socialSeed} from './Social1921Rules';
export interface ZodiacPlayback {selected:number;cells:number[];awards:Win[];}
export class GoldenZodiacSlot extends Social2230LineSlot {
 readonly selectionTitle='이번 회전의 황금 별자리를 고르세요';readonly selectionLabels=['해시계','월식 고리','천체 망원경'];
 readonly presentation=socialPresentation('회전 전에 선택한 별자리만 황금 당첨','선택 별자리 두 배');
 readonly config=this.namedConfig('golden-zodiac-choice','황금 별자리 선택','GOLDEN ZODIAC CHOICE',['해시계','월식 고리','천체 망원경','천문판','성도 두루마리','관측종','측량 컴퍼스','혜성 깃발','황도 WILD'],'회전 전에 세 별자리 중 하나 선택. AUTO는 마지막 선택 유지.\n선택 심볼의 당첨 라인만 ×2. 선택은 베팅별 저장.\n선택 후보 세 종류는 동일 등장률·배당으로 설계.\n같은 스핀 도중 선택 변경 불가. 별도 무료 회전·구매 없음.','#252f4e','#dace86');
 constructor(){super();for(let n=0;n<3;n++){this.config.symbols[n].weight=6;this.config.symbols[n].payout=this.pays[0][2];}}
 selectionForBet(bet:number){const n=this.state(bet,[0])[0];return n<3?n:0;}
 evaluate(board:string[],bet:number){
  if(!Number.isInteger(this.selection)||this.selection<0||this.selection>2)throw Error('Invalid zodiac selection');
  const r=super.evaluate(board,bet),pays=this.pays.map((row,n)=>row.map(v=>v*(n===this.selection?2:1)));
  r.wins=awardLines(this.config,board,bet,pays);const awards=r.wins.filter(w=>w.symbol===this.config.id+'-'+this.selection);
  r.zodiacFeature={selected:this.selection,cells:board.flatMap((id,c)=>id===this.config.id+'-'+this.selection?[c]:[]),awards};return sumResult(r);
 }
 spin(bet:number,rng:()=>number=Math.random){const r=this.draw(bet,rng);r.progressUpdate=this.update(bet,[this.selection]);return r;}

 get pays(){return SOCIAL_2230_PAYS.map((row,i)=>(i<3?SOCIAL_2230_PAYS[0]:row).map(n=>n*1.7605));}
 demoSpin(bet:number){const rng=socialSeed(25+this.selection);for(let i=0;i<20000;i++){const r=this.spin(bet,rng);if(r.zodiacFeature!.awards.length)return r;}throw Error('Zodiac preview unavailable');}
}
