import {Node,Graphics,Vec3} from 'cc';
import {petArt} from './PixelArt';
/** Owns one pet across UI redraws and round phases. Time and travel never reset on render. */
export class PetRoamer {
 readonly layer:Node;private pet:Node|null=null;private frames:Node[]=[];private id='';private elapsed=0;private direction=-1;private x=0;private y=0;private targetY=0;private left=50;private right=670;private scale=3;private initialized=false;
 constructor(parent:Node){this.layer=new Node('Persistent pet layer');this.layer.layer=parent.layer;parent.addChild(this.layer);}
 place(id:string|undefined,floor:number,scale:number,left:number,right:number){
  this.layer.active=!!id;this.targetY=floor;this.left=left;this.right=right;this.scale=Math.max(2,scale*.65);
  if(!id)return;if(id!==this.id){this.id=id;this.pet?.destroy();this.pet=new Node('Roaming pet '+id);this.pet.layer=this.layer.layer;this.layer.addChild(this.pet);this.frames=[0,1].map(frame=>{const n=new Node('Pet frame '+frame);n.layer=this.layer.layer;this.pet!.addChild(n);petArt(n.addComponent(Graphics),id,0,0,1,frame);return n;});}
  if(!this.initialized){this.x=right;this.y=floor;this.initialized=true;}
 }
 update(dt:number){if(!this.pet||!this.layer.active)return;dt=Math.min(dt,.1);this.elapsed+=dt;this.x+=this.direction*130*dt;if(this.x<this.left){this.x=this.left;this.direction=1;}if(this.x>this.right){this.x=this.right;this.direction=-1;}this.y+=(this.targetY-this.y)*Math.min(1,dt*4);const bob=Math.sin(this.elapsed*9)*this.scale*1.5+Math.sin(this.elapsed*.8)*this.scale*3;this.pet.setPosition(this.x,this.y+bob);this.pet.setScale(this.direction*this.scale,this.scale,1);const frame=Math.floor(this.elapsed/.2)%2;this.frames.forEach((n,i)=>n.active=i===frame);}
 align(position:Vec3,index:number){this.layer.setPosition(position);this.layer.setSiblingIndex(index);}
 sync(id:string|undefined){this.place(id,this.targetY,this.scale/.65,this.left,this.right);}
 hide(){this.layer.active=false;}
 destroy(){this.layer.destroy();}
}
